  ('Kedai Es Segar', 'Es Teh Jumbo, Jus & Gorengan', 'Minuman dingin dan gorengan favorit mahasiswa siang hari. Es teh jumbo, es jeruk peras asli, dan jus segar tanpa pengawet.', 'Selasar Penghubung Gedung Sipil & Mesin', 'Selasar Gedung Sipil & Mesin', '08.00', '17.00', true, 4.8, 240, '3-5 menit', 'https://lh3.googleusercontent.com/aida-public/AB6AXuBrdvatxrSgSv_bk9F2ItCBtvfJ3HaNQPATyABuMQp7jQjE3pqxGsUP1SsWVwP0Vg3s5s9cNUl3RRBi0rABuoi8VhwD21M3nrYlBvVX8dOJ3ddckhyCmxgNz1eAreCoM71tumh3HHGAeoaZs41oQiatSfUXnG40bUUUwQnxk8mmPi9TDipJED4nqGCVaoCLMhZx7oBsXZAZn7U6PzPaIBRATWXgkc6DW0ZOSiqJWAM'),
  ('Dapur Mahasiswa', 'Nasi Goreng Mawut & Paket Hemat', 'Buka untuk shift sore dan malam. Nasi goreng mawut wok smokey dan paket hemat mulai Rp10.000 untuk anak kos dan mahasiswa lembur.', 'Pujasera Belakang Gedung Dekanat FT', 'Pujasera Dekanat', '16.00', '22.00', false, 4.7, 95, '10-15 menit', 'https://lh3.googleusercontent.com/aida-public/AB6AXuAXG-sTqRBr9UGV3wvtDFDpl1fMM-nUePynnpenoG_sj-ZkZo72nr9KS0wK3AZBtVUJHHpiSAhIA14jtQWMMQV6jYXJR-guY8mDm_ZgNYJ_9trp2iOgu7Xi2w_S_L4ANV0I6HgCvixsudPPRcwOUpQU-26KgO5IOE9tUXzETYZUnqxdGuodwNVN8SKUoScU3RPCzpH9ufyGZTgpgtQMBiT2adrbMeEZijHsqRwWr5M');
insert into menus (kios_id, category_id, name, description, price, original_price, rating, review_count, image_url, is_available, is_popular, tags, prep_time) values
  (1, 1, 'Nasi Ayam Geprek Sambal Korek', 'Menu andalan mahasiswa Teknik Undip! Dada/paha ayam digoreng krispi dengan tepung bumbu renyah, digeprek bersama cabai rawit pedas dan bawang putih gurih. Disajikan hangat dengan nasi putih pulen, lalapan mentimun dan kol goreng.', 15000, 18000, 4.9, 142, 'https://lh3.googleusercontent.com/aida-public/AB6AXuA826TzayIznN9pLDXvr0irpvwHbeLAl8B-yh-DQqltAlD5utk5nkETuoO2xRg4-LB4vk6o3vGdsXqqwYkNUgAe_q7QfXz-ZiG7iQFwP8L1sCGTE7lYH_6gzfu769SwFQQXuvOOhsa_yQ3DSBJgxQgQE9KuYkbyfGvHm6uA8IL-JeBAqtuqXF4TdBLkad7cbcHpE9q6bbpbT06QOh3m5M9fIA_IAWEz58mB_AF-rJU', true, true, array['Pedas','Halal','Ayam Segar'], '10-15 menit'),
  (1, 1, 'Nasi Ayam Geprek Mozzarella', 'Ayam geprek krispi dengan topping lelehan keju mozzarella torch, gurih dan creamy. Cocok buat yang suka pedas tapi tetap lembut.', 18000, null, 4.8, 96, 'https://lh3.googleusercontent.com/aida-public/AB6AXuA0IQRaaDJ8i_7n0fMp2xrKUkrWyMQHFwKKtL04CHdoVFnnc53h408bR8oYiqYpbFc6_xq1J2SgL_XUqhtf72rQ7jZKX8XSNLUbxgyntmsccBqFdJidUCjgeQWxQfDFk6RfNvyOqek2GG-uy41vjLVWks4yMJkszdPtRWGT5UoXFZwNBUX23Xm0vQc4O0iAaIlSDoZUYUrLBE97RnPaGTO9_RpkVU9JYn8Jeb-mZHA', true, false, array['Pedas','Halal','Keju'], '10-15 menit'),
  (1, 5, 'Paket Hemat Geprek + Es Teh', 'Porsi kenyang: nasi geprek lengkap dengan es teh manis dingin. Paket andalan akhir bulan.', 17000, 21000, 5.0, 120, 'https://lh3.googleusercontent.com/aida-public/AB6AXuB8vkkBfsPbx4XalVUBwR1On_imCmhRgZyIz-VT5LuHyxmeqnkZKHcJRtk_YARj7AFvNC6tSRzuUSO7TaTyWEa31LfsVDWdSllHpllFTr59KlPJow3qH1oQQH_ynl3V4khLVpD87priszrvEmiZKqFUtytxTn_Ex9vunGFKmLWrwhUtcwWiyGGlFce_Oio6lYCLSXzZvvHJKIYrMdAjiC7Z7aPCGvkNPG4AoF_WrmM', true, true, array['Hemat','Halal','Paket'], '10 menit'),
