  (2, 4, 'Gado-gado Komplit', 'Sayuran rebus segar, tahu, tempe, lontong, dan telur dengan siraman bumbu kacang kental. Menu sehat dan mengenyangkan.', 12000, null, 4.8, 87, 'https://lh3.googleusercontent.com/aida-public/AB6AXuAHB5oH0uV_4Q1FHCcaUVgGsAvPph122gjeWrM2ShNQEnRX2wINo3zjtJh8PANGH2cgfwUiGlJcj8IO7nkQiYgqS5t3j9ymj79ewPTrATU7DlrcsjIv4-FhiW0vSuo1qV5YgSaPeQYoT_9TMcloRkvxbQtoVLDGeDyUlQt7AZWqIXwq_bpmjboDSdAmm7okCSCa6s-lQN8W5mzHdxpo412SNeAMrHkSv7vMiSpr4G0', true, false, array['Vegetarian','Halal','Sehat'], '7 menit'),
